insert into learning_phases (id, slug, title, summary) values (5, 'ia-pour-les-metiers', 'IA pour les métiers', 'Appliquer l''IA dans votre fonction : marketing et communication, ressources humaines, juridique, finance.') on conflict (id) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M19', 'ia-contenu-marketing', 'IA pour le contenu marketing et la communication', 'Produire des contenus de marque de qualité avec l''IA : brief, voix de marque, formats, relecture et validation humaine.', 5, 19, 'coming_soon', 'beginner', 5, array['Brief et ligne éditoriale', 'Voix de marque et guide de style', 'Production de contenus multi-formats', 'Relecture, vérification des faits et droits', 'Workflow de contenu avec validation humaine']::text[], array['Un assistant IA', 'Tableur']::text[], array['Rédiger un brief exploitable par un assistant IA', 'Encoder une voix de marque dans des instructions réutilisables', 'Mettre en place un circuit de relecture et de validation']::text[], 'Guide de production de contenu assisté par IA pour une marque', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M20', 'ia-acquisition-seo-geo', 'IA pour l''acquisition, le SEO et le GEO', 'Gagner en visibilité et en performance : recherche d''audience, SEO, visibilité dans les assistants IA (GEO), tests et analyse de campagnes.', 5, 20, 'coming_soon', 'intermediate', 5, array['Études d''audience et personas assistés', 'SEO sémantique et GEO', 'Segmentation et personnalisation', 'Tests A/B et lecture de résultats', 'Automatisation de campagnes sans code']::text[], array['Un assistant IA', 'Tableur', 'Outil d''automatisation no-code']::text[], array['Construire un plan de contenus orienté SEO et GEO', 'Concevoir un test A/B et en lire les résultats avec prudence', 'Automatiser une tâche de campagne sans code']::text[], 'Plan d''acquisition et de tests pour une campagne', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M21', 'ia-reputation-communication-responsable', 'Réputation, veille et communication responsable', 'Veiller, répondre et communiquer avec l''IA en maîtrisant les risques : crise, contenus synthétiques, transparence, cadre légal général.', 5, 21, 'coming_soon', 'intermediate', 5, array['Veille et analyse de sentiment', 'Gestion de crise sous contrôle humain', 'Contenus synthétiques et authenticité', 'Transparence sur l''usage de l''IA', 'Repères juridiques : publicité, droit à l''image, données personnelles']::text[], array['Un assistant IA', 'Tableur']::text[], array['Mettre en place une veille outillée avec ses limites', 'Préparer des réponses de crise validées par des humains', 'Rédiger une charte d''usage de l''IA en communication']::text[], 'Charte d''usage de l''IA en communication et plan de réponse à incident (ne constitue pas un avis juridique)', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M22', 'ia-recrutement', 'IA pour le recrutement et la marque employeur', 'Recruter avec l''IA de façon efficace et équitable : offres, sourcing, présélection, entretiens, biais et obligations de l''AI Act.', 5, 22, 'coming_soon', 'intermediate', 5, array['Rédaction d''offres et de scorecards', 'Sourcing et présélection assistés', 'Biais et équité', 'Entretiens structurés', 'AI Act : systèmes de recrutement à haut risque']::text[], array['Un assistant IA', 'Tableur']::text[], array['Concevoir un processus de recrutement avec points de contrôle humain', 'Repérer et mesurer des risques de biais', 'Situer un outil de recrutement dans le cadre de l''AI Act']::text[], 'Processus de recrutement assisté par IA avec registre de risques (ne constitue pas un avis juridique)', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M23', 'ia-competences-formation-rh', 'IA pour les compétences, la formation et l''onboarding', 'Cartographier les compétences, personnaliser les parcours de développement et accélérer l''intégration avec l''IA.', 5, 23, 'coming_soon', 'beginner', 5, array['Cartographie des compétences', 'Parcours de développement personnalisés', 'Onboarding assisté', 'Création de supports de formation', 'Mesure de l''efficacité']::text[], array['Un assistant IA', 'Tableur']::text[], array['Construire une cartographie de compétences exploitable', 'Concevoir un parcours d''intégration assisté par IA', 'Mesurer l''effet d''une action de formation']::text[], 'Plan de développement des compétences d''une équipe assisté par IA', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M24', 'ia-pilotage-rh-dialogue-social', 'IA, pilotage RH et dialogue social', 'Piloter avec les données RH et déployer des assistants internes dans un cadre protecteur : RGPD, dialogue social, conduite du changement.', 5, 24, 'coming_soon', 'advanced', 5, array['People analytics responsable', 'Données RH sensibles et RGPD', 'Assistants RH internes', 'Information et consultation des représentants du personnel', 'Conduite du changement RH']::text[], array['Un assistant IA', 'Tableur']::text[], array['Définir des indicateurs RH utiles et proportionnés', 'Cadrer un assistant RH interne', 'Préparer la concertation avec les représentants du personnel']::text[], 'Cadre de gouvernance d''un assistant RH (ne constitue pas un avis juridique)', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M25', 'ia-recherche-juridique', 'IA pour la recherche et l''analyse juridiques', 'Rechercher, synthétiser et rédiger avec l''IA sans perdre en rigueur : hallucinations, vérification des sources, confidentialité.', 5, 25, 'coming_soon', 'intermediate', 5, array['Recherche assistée et vérification des sources', 'Hallucinations et citations inventées', 'Synthèse de textes et de décisions', 'Veille réglementaire', 'Secret professionnel et confidentialité']::text[], array['Un assistant IA', 'Base de données juridique de votre organisation']::text[], array['Mettre en place un protocole de vérification des sources', 'Rédiger une note assistée avec traçabilité', 'Choisir ce qu''on peut ou non soumettre à un outil d''IA']::text[], 'Protocole de recherche juridique assistée avec contrôle des sources', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M26', 'ia-contrats-conformite', 'IA pour les contrats et la conformité', 'Industrialiser la revue de contrats et la conformité : playbooks, clausiers, due diligence, legal ops et automatisation sans code.', 5, 26, 'coming_soon', 'intermediate', 6, array['Revue de contrats assistée', 'Playbooks et clausiers', 'Due diligence', 'Legal ops et automatisation sans code', 'Cartographie et suivi des risques']::text[], array['Un assistant IA', 'Tableur', 'Outil d''automatisation no-code']::text[], array['Construire un playbook de revue de contrat exploitable par une IA', 'Définir les points d''escalade vers un juriste', 'Automatiser un flux de suivi de contrats sans code']::text[], 'Playbook de revue de contrat assistée par IA', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M27', 'droit-de-l-ia', 'Droit de l''IA : AI Act, données et propriété intellectuelle', 'Les repères juridiques pour accompagner l''IA en entreprise : AI Act, RGPD, propriété intellectuelle, responsabilité et contrats avec les fournisseurs.', 5, 27, 'coming_soon', 'advanced', 6, array['AI Act : classification des risques et obligations', 'RGPD et IA', 'Propriété intellectuelle et contenus générés', 'Responsabilité', 'Contrats avec les fournisseurs d''IA']::text[], array['Navigateur']::text[], array['Qualifier un cas d''usage au regard de l''AI Act', 'Identifier les points RGPD d''un projet d''IA', 'Préparer les clauses clés d''un contrat avec un fournisseur d''IA']::text[], 'Note d''analyse de conformité d''un cas d''usage IA (ne constitue pas un avis juridique)', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M28', 'ia-controle-gestion-fpa', 'IA pour le contrôle de gestion et le FP&A', 'Accélérer reporting, analyse d''écarts, prévisions et scénarios avec l''IA, tout en gardant la maîtrise des chiffres.', 5, 28, 'coming_soon', 'intermediate', 5, array['Reporting et tableaux de bord', 'Analyse d''écarts', 'Prévisions et scénarios', 'Narratifs de gestion', 'Qualité et traçabilité des données']::text[], array['Un assistant IA', 'Tableur']::text[], array['Produire un reporting mensuel assisté avec contrôles', 'Expliquer des écarts avec traçabilité', 'Construire des scénarios comparables']::text[], 'Pack de reporting mensuel assisté par IA avec explication d''écarts', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M29', 'ia-comptabilite-tresorerie-audit', 'IA pour la comptabilité, la trésorerie et l''audit', 'Automatiser les tâches comptables et de trésorerie, détecter les anomalies et renforcer l''audit avec une piste de contrôle claire.', 5, 29, 'coming_soon', 'intermediate', 5, array['Extraction de documents', 'Rapprochements et détection d''anomalies', 'Prévision de trésorerie', 'Contrôles internes et audit', 'Piste d''audit']::text[], array['Un assistant IA', 'Tableur', 'Outil d''automatisation no-code']::text[], array['Concevoir un contrôle assisté par IA avec piste d''audit', 'Mesurer la fiabilité d''une extraction de documents', 'Construire une prévision de trésorerie simple']::text[], 'Procédure de contrôle assisté par IA avec piste d''audit', false) on conflict (code) do nothing;
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M30', 'ia-risque-gouvernance-finance', 'Risques, conformité et gouvernance de l''IA en finance', 'Gouverner l''IA dans un environnement financier : risque de modèle, explicabilité, fraude, cadre réglementaire général et sous-traitance.', 5, 30, 'coming_soon', 'advanced', 6, array['Risque de modèle', 'Explicabilité', 'Lutte contre la fraude et conformité', 'AI Act et secteur financier', 'Résilience et sous-traitance']::text[], array['Tableur']::text[], array['Cartographier les risques d''un cas d''usage IA en finance', 'Définir des exigences d''explicabilité et de contrôle', 'Évaluer un prestataire d''IA']::text[], 'Cadre de gouvernance d''un cas d''usage IA en finance (ne constitue pas un avis juridique)', false) on conflict (code) do nothing;
